-- =============================================================================
-- English Lab - V19: banco ampliado de los objetivos 13-14
-- Lleva PASSIV (13) y REPSP (14), ambos B2, a 100 actividades cada uno.
-- 100 filas nuevas por objetivo, ids explicitos 1201-1300 y 1301-1400
-- (overriding system value). level B2, skill grammar, categoria 2.
-- La clave sigue viviendo SOLO en el jsonb `content` (answer/accepted);
-- jamas viaja al navegador (el DTO de estudiante la omite).
-- Aprox. 60% MULTIPLE_CHOICE y 40% FILL_BLANK; sin prompts repetidos.
-- =============================================================================

-- Igual que en V13/V14/V17: en una base de pruebas reutilizada, filas
-- autoincrementales pueden ocupar el rango 1201-1400 y romper la PK. Se liberan
-- SOLO actividades de prueba (objetivos fuera del seed 1-14); en produccion no
-- borra nada. attempts/assignments caen en cascada por sus FK.
delete from activities
where id between 1201 and 1400
  and objective_id not between 1 and 14;

insert into activities (id, objective_id, type, level, skill, title, content, category_id) overriding system value values
