    -- objetivo 14: REPSP (B2) - categoria 2 Tiempos verbales. 100 filas (1301-1400).
    (1301, 14, 'MULTIPLE_CHOICE', 'B2', 'grammar', 'Tell with an object',
        '{"prompt":"She ___ me that she was tired.","options":[{"id":"a","text":"said"},{"id":"b","text":"spoke"},{"id":"c","text":"told"},{"id":"d","text":"tells"}],"answer":"c","explanation":"Tell necesita un objeto indirecto (tell somebody). Say no lleva objeto de persona: she said that..."}',
        2),
    (1302, 14, 'MULTIPLE_CHOICE', 'B2', 'grammar', 'Say without an object',
        '{"prompt":"He ___ that he would arrive late.","options":[{"id":"a","text":"told"},{"id":"b","text":"said"},{"id":"c","text":"tells"},{"id":"d","text":"says"}],"answer":"b","explanation":"Say no necesita objeto de persona. Told exigiria un complemento como me o us."}',
        2),
    (1303, 14, 'MULTIPLE_CHOICE', 'B2', 'grammar', 'Tell us the news',
        '{"prompt":"They ___ us they were moving to Canada.","options":[{"id":"a","text":"said"},{"id":"b","text":"spoke"},{"id":"c","text":"talked"},{"id":"d","text":"told"}],"answer":"d","explanation":"La estructura es tell + persona + that. Sin la persona usariamos said."}',
        2),
    (1304, 14, 'MULTIPLE_CHOICE', 'B2', 'grammar', 'Teacher said',
        '{"prompt":"My teacher ___ that the exam would be difficult.","options":[{"id":"a","text":"told"},{"id":"b","text":"tells"},{"id":"c","text":"say"},{"id":"d","text":"said"}],"answer":"d","explanation":"Con that y sin objeto de persona el verbo es said. Would ya esta en pasado dentro del reporte."}',
        2),
    (1305, 14, 'MULTIPLE_CHOICE', 'B2', 'grammar', 'Tell me about the keys',
        '{"prompt":"He ___ me he had lost his keys.","options":[{"id":"a","text":"said"},{"id":"b","text":"spoke"},{"id":"c","text":"told"},{"id":"d","text":"says"}],"answer":"c","explanation":"Told me es la forma correcta: tell + objeto + la informacion. El pasado had lost mantiene el backshift."}',
        2),
    (1306, 14, 'MULTIPLE_CHOICE', 'B2', 'grammar', 'Busy after the report',
        '{"prompt":"\"I am busy,\" she said. She said she ___ busy.","options":[{"id":"a","text":"was"},{"id":"b","text":"is"},{"id":"c","text":"has been"},{"id":"d","text":"will be"}],"answer":"a","explanation":"En el estilo indirecto el presente pasa a pasado: am se convierte en was."}',
        2),
    (1307, 14, 'MULTIPLE_CHOICE', 'B2', 'grammar', 'Call you later',
        '{"prompt":"\"We will call you,\" they said. They said they ___ call me.","options":[{"id":"a","text":"would"},{"id":"b","text":"will"},{"id":"c","text":"would have"},{"id":"d","text":"are going"}],"answer":"a","explanation":"Will cambia a would cuando el verbo que introduce el reporte esta en pasado."}',
        2),
    (1308, 14, 'MULTIPLE_CHOICE', 'B2', 'grammar', 'Can swim',
        '{"prompt":"\"I can swim,\" he said. He said he ___ swim.","options":[{"id":"a","text":"can"},{"id":"b","text":"could"},{"id":"c","text":"would can"},{"id":"d","text":"could to"}],"answer":"b","explanation":"Can pasa a could en el backshift. Tras could va el verbo base, sin to."}',
        2),
    (1309, 14, 'MULTIPLE_CHOICE', 'B2', 'grammar', 'May be late',
        '{"prompt":"\"I may be late,\" she said. She said she ___ be late.","options":[{"id":"a","text":"may"},{"id":"b","text":"might have"},{"id":"c","text":"would might"},{"id":"d","text":"might"}],"answer":"d","explanation":"May cambia a might al pasar la frase a estilo indirecto con un verbo en pasado."}',
        2),
    (1310, 14, 'MULTIPLE_CHOICE', 'B2', 'grammar', 'Must wear a helmet',
        '{"prompt":"\"You must wear a helmet,\" the coach said. The coach said I ___ wear a helmet.","options":[{"id":"a","text":"must to"},{"id":"b","text":"musted"},{"id":"c","text":"have to"},{"id":"d","text":"had to"}],"answer":"d","explanation":"Must se convierte en had to cuando el reporte esta en pasado. Musted no existe."}',
        2),
    (1311, 14, 'MULTIPLE_CHOICE', 'B2', 'grammar', 'Saw the film',
        '{"prompt":"\"I saw the film,\" he said. He said he ___ the film.","options":[{"id":"a","text":"had seen"},{"id":"b","text":"saw"},{"id":"c","text":"was seeing"},{"id":"d","text":"sees"}],"answer":"a","explanation":"El pasado simple pasa a past perfect en el estilo indirecto: saw se convierte en had seen."}',
        2),
    (1312, 14, 'MULTIPLE_CHOICE', 'B2', 'grammar', 'Working now',
