        2),
    (1316, 14, 'MULTIPLE_CHOICE', 'B2', 'grammar', 'Where do you live',
        '{"prompt":"\"Where do you live?\" he asked. He asked me where I ___.","options":[{"id":"a","text":"lived"},{"id":"b","text":"live"},{"id":"c","text":"did I live"},{"id":"d","text":"do I live"}],"answer":"a","explanation":"En las preguntas indirectas no hay inversion ni do: where I lived. El presente pasa a pasado."}',
        2),
    (1317, 14, 'MULTIPLE_CHOICE', 'B2', 'grammar', 'Are you ready',
        '{"prompt":"\"Are you ready?\" she asked. She asked me ___ I was ready.","options":[{"id":"a","text":"that"},{"id":"b","text":"what"},{"id":"c","text":"if"},{"id":"d","text":"do"}],"answer":"c","explanation":"Las preguntas de si/no se introducen con if. Ademas el presente is pasa a was."}',
        2),
    (1318, 14, 'MULTIPLE_CHOICE', 'B2', 'grammar', 'Train departure time',
        '{"prompt":"\"What time does the train leave?\" he asked. He asked what time the train ___.","options":[{"id":"a","text":"left"},{"id":"b","text":"leave"},{"id":"c","text":"did leave"},{"id":"d","text":"does leave"}],"answer":"a","explanation":"La pregunta indirecta no usa did ni inversion: what time the train left. Leave pasa a left."}',
        2),
    (1319, 14, 'MULTIPLE_CHOICE', 'B2', 'grammar', 'Have you seen my keys',
